    /// <summary>取「可放置出该图格的物品集合」。未收录 → false。</summary>
    public static bool TryGetItemsForTile(int tileType, out IReadOnlyList<int> itemIds)
    {
        if (TileToItems.TryGetValue(tileType, out var items))
        {
            itemIds = items;
            return true;
        }
        itemIds = System.Array.Empty<int>();
        return false;
    }

    /// <summary>取「可放置出该墙的物品集合」。未收录 → false。</summary>
    public static bool TryGetItemsForWall(int wallType, out IReadOnlyList<int> itemIds)
    {
        if (WallToItems.TryGetValue(wallType, out var items))
        {
            itemIds = items;
            return true;
        }
        itemIds = System.Array.Empty<int>();
        return false;
    }
